-- Lua Language Server configuration for checking Factorio Lua against the
-- exact Factorio 2.1.23 API.
--
-- Two pieces are required, and both are needed:
--
--   1. `workspace.library` -> the EmmyLua meta bundle generated by
--      `fmtk docs` from the offline Factorio 2.1.23 API JSON
--      (`.local/factorio-api-offline/2.1.23/luas-addon/factorio/library`).
--      This supplies the exact 2.1.23 class, method, property and event
--      signatures. The Factorio HTML/JSON archive is NOT a LuaLS meta bundle;
--      pointing LuaLS at it directly makes every Factorio global undefined.
--
--   2. the top-level `globals` list -> the runtime global *variables*
--      (game, script, defines, ...). The generated meta bundle declares the
--      *classes* (LuaGameScript, LuaBootstrap, ...), not the global variables,
--      so without this list LuaLS reports every Factorio global as undefined.
--
-- Both `workspace.library` and `--configpath` must be ABSOLUTE paths.
-- During a `--check=<dir>` run LuaLS resolves relative paths against the
-- check target rather than the launching directory, so a relative
-- `--configpath` is silently ignored and no library is loaded at all.
--
-- Regenerate the bundle after any API archive update:
--   fmtk docs -d .local/factorio-api-offline/2.1.23/files/runtime-api.json \
--             -p .local/factorio-api-offline/2.1.23/files/prototype-api.json \
--             --docbase https://lua-api.factorio.com/2.1.23 \
--             .local/factorio-api-offline/2.1.23/luas-addon
return {
  runtime = { version = "Lua 5.2" },
  globals = {
    "game", "script", "defines", "remote", "storage", "prototypes",
    "settings", "data", "mods", "commands", "rendering", "helpers", "log",
  },
  workspace = {
    library = {
      "d:/AI/Factorio-AutoEngineer-Source/.local/factorio-api-offline/2.1.23/luas-addon/factorio/library",
    },
    checkThirdParty = false,
  },
}
